import{_ as n,o as i,c as r,ah as a}from"./chunks/framework.Bja9t6Wf.js";const h=JSON.parse('{"title":"Neuzugang im Archiv: Die Causa Pilnacek","description":"Wir integrieren den Fall Christian Pilnacek und die geheimen Tonaufnahmen in das Projekt. Ein Blick in den Abgrund der Justiz-Interventionen.","frontmatter":{"title":"Neuzugang im Archiv: Die Causa Pilnacek","description":"Wir integrieren den Fall Christian Pilnacek und die geheimen Tonaufnahmen in das Projekt. Ein Blick in den Abgrund der Justiz-Interventionen.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-27-pilnacek-integration.md","filePath":"logbuch/2026-02-27-pilnacek-integration.md"}'),t={name:"logbuch/2026-02-27-pilnacek-integration.md"};function s(l,e,o,u,d,c){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="neuzugang-im-archiv-die-causa-pilnacek" tabindex="-1">Neuzugang im Archiv: Die Causa Pilnacek <a class="header-anchor" href="#neuzugang-im-archiv-die-causa-pilnacek" aria-label="Permalink to &quot;Neuzugang im Archiv: Die Causa Pilnacek&quot;">​</a></h1><p>Heute haben wir entschieden, den <strong>Fall Christian Pilnacek</strong> als zentrales Element in das „Horten-Mysterium“ aufzunehmen. Warum? Weil Pilnacek die personifizierte Schnittstelle zwischen der „Ästhetik des Schweigens“ und der harten politischen Realität ist.</p><p><strong>Was dieser Fall für unsere Mockumentary bedeutet:</strong></p><ul><li><strong>Der Soundtrack der Macht:</strong> Die heimlich aufgenommenen Tonbänder sind das akustische Pendant zu den geschredderten Festplatten. Sie zeigen uns, wie Macht im Hinterzimmer klingt.</li><li><strong>Sobotkas Rolle:</strong> Die Vorwürfe gegen Wolfgang Sobotka („Abdrehen von Ermittlungen“) geben der Figur Sobotka in unserem Drehbuch eine neue, tiefere Dimension. Er ist nicht mehr nur der „Klavierspieler“, sondern der „Dirigent der Verfahren“.</li><li><strong>Die Zwei-Klassen-Justiz:</strong> Dieser Begriff wird zum narrativen Werkzeug, um die privilegierte Behandlung des Horten-Benko-Komplexes zu erklären.</li></ul><p>Der Pilnacek-U-Ausschuss, der gerade in Wien tagt, liefert uns fast täglich neue Dialogzeilen für <strong>Teil 4 des Drehbuchs</strong>.</p><p><em>Dokumentiert von Volti Sodala &amp; Gemini CLI. Februar 2026.</em></p>',6)])])}const m=n(t,[["render",s]]);export{h as __pageData,m as default};
